insert into committees (id, name, slug, event_date, location, contact_public, status, created_by) values ('57a08b12-7dba-458a-a17c-0cce99ec60e4', 'Lomba Desain Poster Fiktif 2027', 'lomba-desain-fiktif', '2027-01-16', 'Galeri Lantai 2 Gedung B, Kampus Fiktif Nusantara, Tangerang', 'Instagram @lombadesainfiktif / email panitia@lombadesainfiktif.contoh.test', 'active', '0f3d402e-e51b-4eb2-aaaa-034651005e07');
